const evaluation=$context.$nodes.XDX_EVALUATE_CONTROL.$output.result;
const state=JSON.parse(JSON.stringify(evaluation.state));
state.nextOperation=evaluation.operation;
state.response={message:evaluation.reason||'Describe a supplier search or draft change.'};
['kind','mode','requestId','revision','payload','source','confirmCommand','attempts','supplier','address','assignments','writeCount','writeOrder','site','SupplierSiteId','continuationCommand'].forEach(function(k){if(Object.prototype.hasOwnProperty.call(evaluation,k))state.response[k]=evaluation[k];});
if(Array.isArray(state.response.attempts))state.response.attempts=state.response.attempts.map(function(attempt){const shown=JSON.parse(JSON.stringify(attempt));if(shown.kind==='supplier')delete shown.sourceSupplierId;return shown;});
if(evaluation.operation==='create_supplier')state.dispatch=JSON.parse(JSON.stringify(evaluation.attempt));
return {operation:evaluation.operation,state:state};

const state=JSON.parse(JSON.stringify($context.$variables.supplierState)),p=state.childDispatch||{},a=state.attempts.filter(function(a){return a.kind===p.kind&&a.requestId===p.requestId&&a.revision===p.revision;})[0],address=p.kind==='address',key=address?'SupplierAddressId':'SupplierContactId',r=$context.$nodes[address?'XDX_GET_CREATED_ADDRESS':'XDX_GET_CREATED_CONTACT'].$output;
 if(!a||a.status!=='accepted')throw new Error('No matching accepted child attempt exists.');
 function decimal(v){return typeof v==='number'&&Number.isSafeInteger(v)&&v>0?String(v):typeof v==='string'&&/^[1-9][0-9]{0,17}$/.test(v)?v:null;}
 const fields=address?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email','AddressPurposeOrderingFlag']:['FirstName','LastName','Email'];
 const generatedMatch=r&&(address?(a.AddressPartyNumber===undefined||String(r.AddressPartyNumber)===String(a.AddressPartyNumber)):(a.PersonProfileId===undefined||decimal(r.PersonProfileId)===decimal(a.PersonProfileId)));
 const matches=generatedMatch&&r&&decimal(r[key])===a[key]&&String(a.suppliers_Id)===String(p.suppliers_Id)&&fields.every(function(f){return r[f]===a.payload[f];})&&(address||Object.prototype.hasOwnProperty.call(r,'PersonProfileId')&&!!decimal(r.PersonProfileId)&&Object.prototype.hasOwnProperty.call(r,'UserName')&&r.UserName===null&&Object.prototype.hasOwnProperty.call(r,'UserAccountStatus')&&r.UserAccountStatus===null);
 a.verification=matches?'verified':'mismatch-or-unavailable';state.nextOperation='display';state.response={message:matches?(address?'Address':'Contact')+' created and independently verified.':'The '+p.kind+' was created, but its saved required fields or relationships could not be verified. It will not be created again.',kind:p.kind,requestId:a.requestId,revision:a.revision,supplier:state.draft&&state.draft.supplier,attempt:JSON.parse(JSON.stringify(a)),verification:a.verification};
 if(matches){state.response.item=JSON.parse(JSON.stringify(r));const resource=address?'addresses':'contacts';state.childSelections=state.childSelections||{};state.childSelections[resource]={suppliers_Id:p.suppliers_Id,item:JSON.parse(JSON.stringify(r))};state.draft=null;delete state.childDispatch;}return {state:state,operation:'display'};
